# Generated by build.py from recipe.yml for recipe http-listen-on-several-urls. Do not edit.
Set-Location $PSScriptRoot
New-Item -ItemType Directory -Force -Path 'site' | Out-Null
[IO.File]::WriteAllText((Join-Path $PWD 'site/hello.txt'), "hello from surl`n")
$server0 = Start-Process surl -ArgumentList '--directory', 'site', 'http://127.0.0.1:8080/', 'http://127.0.0.1:8081/', 'http://localhost:8082/' -PassThru -NoNewWindow
Start-Sleep 1
try { curl.exe http://127.0.0.1:8080/hello.txt --next http://127.0.0.1:8081/hello.txt --next http://localhost:8082/hello.txt } finally { Stop-Process $server0 }
